'use strict';
// A quiet, chat-first shell. Existing practices remain available in the drawer.
document.querySelector('body > aside').id='space-drawer';
$('#space-drawer').inert=true;
const moodLink=$('#space-drawer nav a');moodLink.href='#checkin';moodLink.innerHTML='◈ <span>Mood check-in</span>';
document.querySelector('header').innerHTML='<a class="quiet-brand" href="#chat">aura<span>·</span></a><div class="quiet-header-actions"><a href="#support">Human support</a><button id="space-toggle" aria-expanded="false" aria-controls="space-drawer">Your space ☰</button></div>';
document.querySelector('footer').innerHTML='AI support, not therapy. <a href="#settings">Privacy & about</a>';
$('#space-toggle').onclick=()=>{const open=document.body.classList.toggle('drawer-open');$('#space-drawer').inert=!open;$('#space-toggle').setAttribute('aria-expanded',String(open));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('drawer-open');$('#space-drawer').inert=true;$('#space-toggle').setAttribute('aria-expanded','false');}});
document.querySelectorAll('#space-drawer a').forEach(a=>a.addEventListener('click',()=>{document.body.classList.remove('drawer-open');$('#space-drawer').inert=true;$('#space-toggle').setAttribute('aria-expanded','false');}));
chatPage=function(){return `<section class="quiet-chat" aria-label="Conversation with Aura"><div class="quiet-chat-actions"><button data-chat="new">New conversation</button>${chatMessages.length?'<button data-chat="save">Save to journal</button>':''}</div><div class="chat-transcript" id="chat-transcript" role="log" aria-live="polite" aria-label="Chat messages">${chatMessages.length?chatMessages.map(m=>`<div class="message ${m.role}"><div class="bubble">${m.role==='assistant'?'<span class="message-label">aura</span>':''}${esc(m.text)}</div></div>`).join(''):'<div class="quiet-hello"><span class="quiet-mark" aria-hidden="true">✳</span><h1>Hey. What’s on your mind?</h1><p>A few words are enough.</p></div>'}${chatBusy?'<div class="typing" aria-label="Aura is responding"><span></span><span></span><span></span></div>':''}</div>${chatError?`<div class="chat-error" role="alert">${esc(chatError)} <button class="secondary" data-chat="retry">Retry</button></div>`:''}<form id="chat-form" class="chat-compose"><label class="sr-only" for="chat-input">Message Aura</label><div class="quiet-input"><textarea id="chat-input" rows="1" maxlength="6000" placeholder="Start wherever you are…" ${chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><button class="primary" id="chat-send" aria-label="Send message" ${chatBusy||!chatConsent?'disabled':''}>${chatBusy?'···':'↑'}</button></div><details class="quiet-privacy" ${chatConsent?'':'open'}><summary>AI & your privacy</summary><label class="check"><input type="checkbox" id="chat-consent" ${chatConsent?'checked':''}><span>Send this conversation to Google Gemini for AI replies. Chat stays in this tab unless you save it. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Provider terms</a></span></label></details><span id="chat-status" class="sr-only">Enter to send. Shift + Enter for a new line.</span></form></section>`;};
catArt=function(coat='#bca48c',accent='#8c7561'){return `<svg viewBox="0 0 140 104" aria-hidden="true"><ellipse cx="67" cy="98" rx="49" ry="3" fill="#473a30" opacity=".06"/><g class="cat-rig"><path class="living-tail" d="M32 62 C8 63 5 36 12 27 C21 17 25 35 18 41" fill="none" stroke="${accent}" stroke-width="9" stroke-linecap="round"/><g class="leg leg-back"><path d="M44 64 L42 91 Q44 96 54 93" fill="none" stroke="${accent}" stroke-width="10" stroke-linecap="round"/></g><g class="leg leg-front"><path d="M94 65 L98 92 Q102 95 109 92" fill="none" stroke="${accent}" stroke-width="9" stroke-linecap="round"/></g><path class="cat-body" d="M27 66 C22 43 48 40 64 47 C82 51 95 42 104 57 L104 80 Q87 88 64 79 Q46 88 32 78Z" fill="${coat}"/><g class="leg leg-near-back"><path d="M40 69 L34 92 Q40 97 48 93" fill="none" stroke="${coat}" stroke-width="11" stroke-linecap="round"/></g><g class="leg leg-near-front"><path d="M91 69 L88 92 Q92 97 102 93" fill="none" stroke="${coat}" stroke-width="10" stroke-linecap="round"/></g><g class="living-head"><path d="M83 52 L80 23 L95 31 Q104 27 114 32 L128 24 L126 52 Q122 68 104 67 Q88 65 83 52" fill="${coat}"/><path d="M85 30 L87 43 L95 35Z M123 31 L115 37 L123 43Z" fill="#d8a38c"/><g class="living-eyes" fill="#40362f"><ellipse cx="97" cy="49" rx="2.1" ry="3"/><ellipse cx="117" cy="49" rx="2.1" ry="3"/></g><g class="sleep-eyes" stroke="#645043" stroke-width="1.8" fill="none" stroke-linecap="round"><path d="M93 50 Q97 54 101 50 M113 50 Q117 54 121 50"/></g><path d="M104 54 L110 54 L107 57Z" fill="#a66f5d"/><path d="M107 57 Q102 62 100 58 M107 57 Q110 62 114 58" fill="none" stroke="#816752" stroke-width="1.2"/><path d="M79 52 L92 54 M80 58 L92 57 M122 54 L136 51 M122 58 L136 59" stroke="#8c7561" stroke-width="1" opacity=".7"/></g><path class="pet-heart" d="M110 12 C103 5 99 15 110 21 C121 15 117 5 110 12Z"/></g></svg>`;};
let catLoop=null,catTick=0;
const reducedCats=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('cats-paused');
renderCats=function(){clearInterval(catLoop);let shelf=$('#cat-shelf');if(!shelf){shelf=document.createElement('div');shelf.id='cat-shelf';document.body.append(shelf);}if(catsHidden){shelf.className='';shelf.innerHTML='<button class="cat-restore" data-cats="show" aria-label="Show cats">Cats ♡</button>';return;}const mood=selectedMood||state.moods.at(-1)?.value||3;shelf.className='cat-shelf living-cats';shelf.innerHTML=`<div class="cat-stage"><div id="cat-note" class="cat-note" role="status" hidden></div><button class="cat-button living-cat" data-cat="Miso" data-behavior="${mood<3?'sleep':'idle'}" data-state="${mood<3?'rest':'curious'}" aria-label="Pet Miso" style="--x:15px;--direction:1">${catArt()}</button><button class="cat-button living-cat" data-cat="Mochi" data-behavior="${mood<3?'sleep':'groom'}" data-state="${mood<3?'rest':'quiet'}" aria-label="Pet Mochi" style="--x:150px;--direction:-1">${catArt('#a6b19a','#7a8e74')}</button></div><details class="cat-options"><summary aria-label="Cat options">···</summary><button data-cats="pause">${document.body.classList.contains('cats-paused')?'Resume':'Pause'}</button><button data-cats="hide">Hide</button></details>`;if(!reducedCats())catLoop=setInterval(animateCats,4800);};
function animateCats(){if(document.hidden||reducedCats())return;const mood=selectedMood||state.moods.at(-1)?.value||3,choices=mood<3?['sleep','sleep','groom','idle','stretch']:mood===5?['walk','pounce','groom','stretch','walk','idle']:['walk','groom','idle','stretch','sleep'];document.querySelectorAll('.living-cat').forEach((cat,i)=>{if(cat.dataset.petting==='yes')return;const behavior=choices[(catTick+i*2)%choices.length];cat.dataset.behavior=behavior;cat.dataset.state=behavior==='sleep'?'rest':'curious';if(behavior==='walk'||behavior==='pounce'){const old=parseInt(cat.style.getPropertyValue('--x'))||0;const x=i===0?(catTick%2?75:8):(catTick%2?155:210);cat.style.setProperty('--direction',x>=old?'1':'-1');cat.style.setProperty('--x',x+'px');}});catTick++;}
document.addEventListener('pointerdown',e=>{const cat=e.target.closest('.living-cat');if(!cat)return;cat.dataset.petting='yes';cat.dataset.behavior='nuzzle';cat.dataset.state='rest';setTimeout(()=>{if(cat.isConnected){cat.dataset.petting='no';cat.dataset.behavior='idle';}},2200);});
const quietRoute=route;
route=function(){document.body.classList.toggle('is-chat',['','#home','#chat'].includes(location.hash));quietRoute();};
window.addEventListener('hashchange',()=>{document.body.classList.toggle('is-chat',['','#home','#chat'].includes(location.hash));if(!location.hash||location.hash==='#home')location.hash='chat';});
if(!location.hash||location.hash==='#home')location.hash='chat';else route();

document.addEventListener('click',e=>{const cat=e.target.closest('.living-cat');if(cat&&e.detail===0){cat.dataset.behavior='nuzzle';cat.dataset.state='rest';}});
